-- Build a node name from quest id + state, e.g. node(15024,'OFFEN') ->
-- 'DQ_15024_OFFEN'. prefix defaults to 'DQ' (village/side); pass 'HQ'/'NQ'
-- for main/other. Returns the string (validated against M.set if known).
function M.node(qid, state, prefix)
  local s = string.format('%s_%s_%s', prefix or 'DQ', tostring(qid), state)
  return s
end

-- True if `name` is a known vanilla dialog node.
function M.is_node(name) return M.set[name] == true end

return M
